const fs=require('fs'),path=require('path');
const root=path.resolve(__dirname,'..'),out=path.join(root,'audit-calitate');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const auditState=require('./audit-state.cjs')(root),{rounds,current}=auditState;
const fixes=JSON.parse(fs.readFileSync(path.join(out,'corectari-runda-1.json'),'utf8'));
const passed=auditState.matchesCurrentData&&current.score===10&&!(current.findings||[]).some(f=>!['resolved','closed','remediat_reverificat'].includes(f.status));
const status=!auditState.matchesCurrentData?'Evaluare istorică: datele au fost modificate după audit. Scorul nu se aplică versiunii curente.':passed?'Audit închis: 10/10 în domeniul declarat':'Corectare / reverificare: '+current.score+'/10';
let html='<!doctype html><html lang="ro"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditul documentației iFLYTEK</title><style>body{font:17px/1.6 system-ui,sans-serif;color:#193347;background:#f5f8fa;max-width:1100px;margin:36px auto;padding:0 24px}a{color:#075f8b}h1{line-height:1.2}nav{display:flex;flex-wrap:wrap;gap:18px}.score{padding:22px;background:#e0eef5;border-left:5px solid #247392;font-size:24px}table{border-collapse:collapse;width:100%;background:white}th,td{padding:12px;border:1px solid #c7d8e2;text-align:left;vertical-align:top}.scroll{overflow:auto}.note{padding:16px;background:#fff4d9}code{overflow-wrap:anywhere}li{margin:10px 0}</style><nav><a href="../INDEX.html">Catalog APK</a><a href="../catalog-parametri-functii/INDEX.html">Dicționare</a><a href="../protocol-comunicare/INDEX.html">Protocol</a><a href="../firmware-analiza/INDEX.html">Firmware</a></nav><h1>Audit independent și corectarea documentației</h1><p class="score">'+esc(status)+'</p><p>Auditor: '+esc(current.reviewer||'auditor_documentatie')+'. Data raportului: '+esc(current.date)+'. Scorul aparține raportului independent; generarea acestei pagini nu modifică evaluarea.</p><p class="note">10/10 înseamnă că nu rămân defecte identificate în domeniul verificat. Nu certifică toate răspunsurile istorice, toate metodele din APK sau funcționarea pe ochelari. Firmware-ul real și traficul de dispozitiv nu au fost disponibile.</p>';
html+='<h2>Runde și decizii</h2><div class="scroll"><table><tr><th>Rundă</th><th>Scor</th><th>Stare</th><th>Dovezi</th></tr>'+rounds.map(r=>'<tr><td>'+esc(r.round)+'</td><td>'+esc(r.score)+'/10</td><td>'+esc(r.status)+'</td><td><a href="'+esc(r.folder)+'/audit.txt">Raport TXT</a> · <a href="'+esc(r.folder)+'/audit.json">Raport JSON</a></td></tr>').join('')+'</table></div><p>Flux aplicat: audit independent → dacă scorul este sub 10, corectarea documentelor și a generatoarelor → verificări tehnice → o nouă evaluare independentă.</p>';
html+='<h2>Criteriile ultimei evaluări</h2><div class="scroll"><table><tr><th>Criteriu</th><th>Puncte</th><th>Constatare</th></tr>'+(current.criteria||[]).map(c=>'<tr><td>'+esc(c.id+' · '+c.criterion)+'</td><td>'+esc(c.score)+'/'+esc(c.max)+'</td><td>'+esc(c.result)+'</td></tr>').join('')+'</table></div>';
html+='<h2>Corectări realizate după prima rundă</h2><ul>'+fixes.changes.map(c=>'<li><b>'+esc(c.finding)+':</b> '+esc(c.change)+'</li>').join('')+'</ul><p><a href="corectari-runda-1.json">Registrul corectărilor</a> · <a href="../catalog-parametri-functii/validare.json">Verificări tehnice</a></p>';
html+='<h2>Acoperire și limite</h2><p>'+esc(current.scope?.coverageNote||'Vezi domeniul exact în raportul independent.')+'</p><h3>Documente incluse</h3><ul>'+(current.scope?.primary||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h3>În afara verificării</h3><ul>'+(current.scope?.excluded||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></html>';
if(fs.existsSync(path.join(root,'imbunatatire-raspunsuri/INDEX.html')))html=html.replace('</style>','</style><p id="analiza-raspunsuri" style="padding:16px;background:#e9f5ef;border-left:4px solid #24694f"><a href="../imbunatatire-raspunsuri/INDEX.html"><strong>Analiza tuturor solicitărilor și îmbunătățirea răspunsurilor</strong></a> · Dovezi, limite și experimente; evaluare separată de acest audit.</p>');
fs.writeFileSync(path.join(out,'INDEX.html'),html);
fs.writeFileSync(path.join(out,'status.json'),JSON.stringify({round:current.round,score:current.score,maximum:10,status:current.status,matchesCurrentData:auditState.matchesCurrentData,changedFiles:auditState.changedFiles,independentReport:current.folder+'/audit.json',qualityScope:current.scope,updatedAt:new Date().toISOString()},null,2));
for(const filename of [path.join(root,'INDEX.html'),path.join(root,'../INDEX.html'),path.join(root,'../../INDEX.html'),path.join(root,'catalog-parametri-functii/INDEX.html'),path.join(root,'protocol-comunicare/INDEX.html'),path.join(root,'firmware-analiza/INDEX.html')]){
  const href=path.relative(path.dirname(filename),path.join(out,'INDEX.html')).replaceAll('\\','/');let text=fs.readFileSync(filename,'utf8');
  const banner='<p id="audit-calitate" style="padding:16px;background:#e0eef5;border-left:4px solid #247392"><a href="'+href+'"><strong>Audit independent al documentației</strong></a> · '+(auditState.matchesCurrentData?esc(current.score)+'/10 · runda '+esc(current.round):'scor istoric '+esc(current.score)+'/10; date modificate, reevaluarea versiunii curente este necesară')+' · domeniul și limitele sunt în raport.</p>';
  text=text.includes('id="audit-calitate"')?text.replace(/<p id="audit-calitate"[\s\S]*?<\/p>/,banner):text.replace(/(<body[^>]*>)/i,'$1'+banner);fs.writeFileSync(filename,text);
}
console.log(JSON.stringify({round:current.round,score:current.score,status:current.status,page:path.join(out,'INDEX.html')}));
